create table public.suppliers (id uuid primary key default gen_random_uuid(),external_id text not null unique,name text not null,source_types text[] not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.part_offers (id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id) on delete cascade,listing_id text null,device_brand text null,device_model text null,part_type text not null,part_reference text null,title text not null,price numeric(12,2) not null check(price>=0),shipping_price numeric(12,2) null check(shipping_price>=0),currency text not null,availability text not null,confidence numeric(5,2) null check(confidence between 0 and 100),source_url text null,retrieved_at timestamptz not null,expires_at timestamptz not null,created_at timestamptz not null default now());
create index part_offers_lookup_idx on public.part_offers(device_brand,device_model,part_type,part_reference);create index part_offers_expiry_idx on public.part_offers(expires_at);
create table public.repair_estimates (id uuid primary key default gen_random_uuid(),listing_id text not null,device_brand text null,device_model text null,diagnostic text null,status text not null,parts_cost_min numeric(12,2) null,parts_cost_expected numeric(12,2) null,parts_cost_max numeric(12,2) null,shipping_estimate numeric(12,2) null,repair_cost_expected numeric(12,2) null,confidence numeric(5,2) null check(confidence between 0 and 100),assumptions jsonb not null default '[]'::jsonb,missing_inputs text[] not null default '{}',created_at timestamptz not null default now(),expires_at timestamptz not null);
create index repair_estimates_listing_idx on public.repair_estimates(listing_id,created_at desc);create index repair_estimates_expiry_idx on public.repair_estimates(expires_at);
create table public.repair_scenarios (id uuid primary key default gen_random_uuid(),repair_estimate_id uuid not null references public.repair_estimates(id) on delete cascade,label text not null,part_type text null,probability numeric(6,5) not null check(probability between 0 and 1),selected_offer_id uuid null references public.part_offers(id) on delete set null,parts_cost numeric(12,2) null,shipping_cost numeric(12,2) null,total_cost numeric(12,2) null,confidence numeric(5,2) null check(confidence between 0 and 100),assumptions jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create index repair_scenarios_estimate_idx on public.repair_scenarios(repair_estimate_id);
alter table public.suppliers enable row level security;alter table public.part_offers enable row level security;alter table public.repair_estimates enable row level security;alter table public.repair_scenarios enable row level security;
comment on table public.part_offers is 'Expiring normalized supplier observations. Mock/dev offers must never be persisted.';
